23	interface AgentStepProps {
24	  title: string;
25	  description: string;
26	  icon: LucideIcon;
27	  status: StepStatus;
28	  delay?: number;
29	  data?: DataItem[];
30	  metrics?: { label: string; value: string }[];
31	  primaryColor?: string;
32	  accentColor?: string;
33	  cardBackgroundColor?: string;
34	  cardBorderColor?: string;
35	  textColor?: string;
36	  secondaryTextColor?: string;
37	  successColor?: string;
38	  borderRadius?: string;
39	  animationSpeed?: string;
40	  compactMode?: boolean;
41	}
