43	export const AgentStep = ({
44	  title,
45	  description,
46	  icon: Icon,
47	  status,
48	  delay = 0,
49	  data = [],
50	  metrics = [],
51	  primaryColor = "#6b7280",
52	  accentColor = "#22c55e",
53	  cardBackgroundColor = "#262626",
54	  cardBorderColor = "#404040",
55	  textColor = "#ffffff",
56	  secondaryTextColor = "#a3a3a3",
57	  successColor = "#22c55e",
58	  borderRadius = "0.5rem",
59	  animationSpeed = "normal",
60	  compactMode = false,
61	}: AgentStepProps) => {
62	  const [loadingItems, setLoadingItems] = useState<Set<number>>(new Set());
63	  const [completedItems, setCompletedItems] = useState<Set<number>>(new Set());
64	  const [expandedItems, setExpandedItems] = useState<Set<number>>(new Set());
65	
66	  useEffect(() => {
67	    if (status === "active" && data.length > 0) {
68	      // Reset states when step becomes active
69	      setLoadingItems(new Set());
70	      setCompletedItems(new Set());
71	      
72	      // Simulate loading each item
73	      data.forEach((_, idx) => {
74	        setTimeout(() => {
75	          setLoadingItems(prev => new Set([...prev, idx]));
76	          
77	          // Complete item after 800ms
78	          setTimeout(() => {
79	            setLoadingItems(prev => {
80	              const next = new Set(prev);
81	              next.delete(idx);
82	              return next;
83	            });
84	            setCompletedItems(prev => new Set([...prev, idx]));
85	          }, 800);
86	        }, idx * 150);
87	      });
88	    } else if (status === "completed") {
89	      // All items completed
90	      setCompletedItems(new Set(data.map((_, idx) => idx)));
91	      setLoadingItems(new Set());
92	    }
93	  }, [status, data.length]);
94	
95	  const animationDuration = animationSpeed === "fast" ? "250ms" : animationSpeed === "slow" ? "750ms" : "500ms";
96	  const padding = compactMode ? "0.75rem" : "1.25rem";
97	
98	  return (
99	    <div
100	      className={cn(
101	        "relative group animate-slide-up opacity-0",
102	        "border bg-card",
103	        "transition-all",
104	        status === "pending" && "border-border",
105	      )}
106	      style={{ 
107	        animationDelay: `${delay}ms`, 
108	        animationFillMode: "forwards",
109	        borderColor: status === "active" ? `${primaryColor}80` : status === "completed" ? `${successColor}4d` : cardBorderColor,
110	        backgroundColor: status === "completed" ? `${successColor}0d` : cardBackgroundColor,
111	        boxShadow: status === "active" ? `0 4px 12px ${primaryColor}33` : undefined,
112	        borderRadius,
113	        padding,
114	        transitionDuration: animationDuration,
115	      }}
116	    >
117	      {/* Status indicator */}
118	      <div className="absolute -left-2 sm:-left-3 top-1/2 -translate-y-1/2">
119	        <div
