1	import { useState, useMemo } from 'react';
2	import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
3	import { ScrollArea } from '@/components/ui/scroll-area';
4	import { Input } from '@/components/ui/input';
