7	import { Search, Download, Filter, MessageSquare } from 'lucide-react';
8	
9	interface AgenticFlowEvent {
10	  type: string;
11	  timestamp: number;
12	  data: any;
13	}
14	
15	interface RealTimeEventLogProps {
16	  events: AgenticFlowEvent[];
17	  maxEvents?: number;
18	}
19	
20	export function RealTimeEventLog({ events, maxEvents = 100 }: RealTimeEventLogProps) {
21	  const [searchTerm, setSearchTerm] = useState('');
22	  const [selectedTypes, setSelectedTypes] = useState<Set<string>>(new Set());
23	
24	  const filteredEvents = useMemo(() => {
25	    return events
26	      .filter(event => {
27	        if (searchTerm && !JSON.stringify(event).toLowerCase().includes(searchTerm.toLowerCase())) {
28	          return false;
29	        }
30	        if (selectedTypes.size > 0 && !selectedTypes.has(event.type)) {
31	          return false;
32	        }
33	        return true;
34	      })
35	      .slice(-maxEvents);
36	  }, [events, searchTerm, selectedTypes, maxEvents]);
37	
38	  const eventTypes = useMemo(() => {
39	    return Array.from(new Set(events.map(e => e.type)));
40	  }, [events]);
41	
42	  const handleExport = () => {
43	    const data = JSON.stringify(filteredEvents, null, 2);
44	    const blob = new Blob([data], { type: 'application/json' });
45	    const url = URL.createObjectURL(blob);
46	    const a = document.createElement('a');
47	    a.href = url;
48	    a.download = `events-${Date.now()}.json`;
49	    a.click();
50	  };
51	
52	  return (
53	    <Card className="border-2 border-primary/20">
54	      <CardHeader>
55	        <div className="flex items-center justify-between">
56	          <CardTitle className="flex items-center gap-2">
57	            <MessageSquare className="w-5 h-5 text-green-500" />
58	            Event Log
59	            <Badge variant="outline">{filteredEvents.length}</Badge>
60	          </CardTitle>
61	          <Button size="sm" variant="outline" onClick={handleExport}>
62	            <Download className="w-4 h-4 mr-1" /> Export
63	          </Button>
64	        </div>
65	      </CardHeader>
66	      <CardContent className="space-y-4">
67	        {/* Search and Filter */}
68	        <div className="flex gap-2">
69	          <div className="relative flex-1">
70	            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
71	            <Input
72	              placeholder="Search events..."
73	              value={searchTerm}
74	              onChange={(e) => setSearchTerm(e.target.value)}
75	              className="pl-9"
76	            />
77	          </div>
78	          <Button variant="outline" size="icon">
79	            <Filter className="w-4 h-4" />
80	          </Button>
81	        </div>
82	
83	        {/* Event Type Filters */}
84	        {eventTypes.length > 0 && (
85	          <div className="flex flex-wrap gap-2">
86	            {eventTypes.map(type => (
87	              <Badge
88	                key={type}
89	                variant={selectedTypes.has(type) ? 'default' : 'outline'}
90	                className="cursor-pointer transition-all hover:scale-105"
91	                onClick={() => {
92	                  const newTypes = new Set(selectedTypes);
93	                  if (newTypes.has(type)) {
94	                    newTypes.delete(type);
95	                  } else {
96	                    newTypes.add(type);
97	                  }
98	                  setSelectedTypes(newTypes);
99	                }}
100	              >
101	                {type}
102	              </Badge>
103	            ))}
104	          </div>
105	        )}
106	
107	        {/* Event List */}
108	        <ScrollArea className="h-[400px] border rounded-lg">
109	          <div className="space-y-2 p-3 font-mono text-xs">
110	            {filteredEvents.length > 0 ? (
111	              filteredEvents.map((event, index) => (
112	                <div
113	                  key={index}
114	                  className="p-3 rounded-lg border bg-muted/30 hover:bg-muted/50 transition-colors animate-fade-in"
115	                >
116	                  <div className="flex items-start justify-between gap-2 mb-1">
117	                    <Badge variant="outline" className="text-xs">
118	                      {event.type}
119	                    </Badge>
120	                    <span className="text-muted-foreground">
121	                      {new Date(event.timestamp).toLocaleTimeString()}
122	                    </span>
123	                  </div>
124	                  <pre className="text-xs overflow-x-auto whitespace-pre-wrap">
125	                    {JSON.stringify(event.data, null, 2)}
126	                  </pre>
127	                </div>
128	              ))
129	            ) : (
130	              <div className="text-center text-muted-foreground py-8">
131	                {events.length === 0 ? 'No events yet...' : 'No events match your filters'}
132	              </div>
133	            )}
134	          </div>
135	        </ScrollArea>
136	      </CardContent>
137	    </Card>
138	  );
139	}

