134	function convertPlanToGraph(
135	  actions: Action[],
136	  currentActionId?: string,
137	  completedActionIds: string[] = []
138	): { nodes: Node[]; edges: Edge[] } {
139	  const nodes: Node[] = actions.map((action, index) => {
140	    const isCompleted = completedActionIds.includes(action.id);
141	    const isCurrent = action.id === currentActionId;
142	
143	    return {
144	      id: action.id,
145	      position: calculateNodePosition(index, actions.length),
146	      data: {
147	        label: (
148	          <div className="text-center">
149	            <div className="font-semibold text-sm">{action.name}</div>
150	            <div className="text-xs text-muted-foreground">Cost: {action.cost}</div>
151	          </div>
152	        )
153	      },
154	      style: {
155	        background: isCompleted
156	          ? 'linear-gradient(135deg, #10b981 0%, #059669 100%)'
157	          : isCurrent
158	          ? 'linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%)'
159	          : 'linear-gradient(135deg, #64748b 0%, #475569 100%)',
160	        color: 'white',
161	        border: isCurrent ? '2px solid #a855f7' : '1px solid transparent',
162	        borderRadius: '8px',
163	        padding: '12px',
164	        width: 180,
165	        boxShadow: isCurrent ? '0 0 20px rgba(168, 85, 247, 0.5)' : undefined
166	      }
167	    };
168	  });
169	
170	  const edges: Edge[] = [];
171	  for (let i = 0; i < actions.length - 1; i++) {
172	    const isCompleted = completedActionIds.includes(actions[i].id);
173	    edges.push({
174	      id: `${actions[i].id}-${actions[i + 1].id}`,
175	      source: actions[i].id,
176	      target: actions[i + 1].id,
177	      animated: actions[i + 1].id === currentActionId,
178	      style: {
179	        stroke: isCompleted ? '#10b981' : '#64748b',
180	        strokeWidth: 2
181	      },
182	      markerEnd: {
183	        type: MarkerType.ArrowClosed,
184	        color: isCompleted ? '#10b981' : '#64748b'
185	      }
186	    });
187	  }
188	
189	  return { nodes, edges };
190	}
191	
192	function calculateNodePosition(index: number, total: number): { x: number; y: number } {
193	  const nodesPerRow = Math.ceil(Math.sqrt(total));
194	  const row = Math.floor(index / nodesPerRow);
195	  const col = index % nodesPerRow;
196	
197	  return {
198	    x: col * 250,
199	    y: row * 150
200	  };
201	}

