193	function formatDuration(ms: number): string {
194	  if (ms < 1000) return `${ms}ms`;
195	  const seconds = Math.floor(ms / 1000);
196	  if (seconds < 60) return `${seconds}s`;
197	  const minutes = Math.floor(seconds / 60);
198	  const remainingSeconds = seconds % 60;
199	  if (minutes < 60) return `${minutes}m ${remainingSeconds}s`;
200	  const hours = Math.floor(minutes / 60);
201	  const remainingMinutes = minutes % 60;
202	  return `${hours}h ${remainingMinutes}m`;
203	}
